623	/**
624	 * @brief 保守判断：这个画布坐标包围盒是否**可能**写到任何像素。
625	 *
626	 * 所有写路径（put_pixel / blend_pixel / blend_span / cover_span_fp）都同时受
627	 * 画布边界与裁剪矩形限制，所以"盒与（画布 ∩ 裁剪）不相交"⇒ 一个像素都不会写。
628	 * 于是完全在画布外、或完全在脏区外的**图元可以整条跳过**，连投影后的简化、
629	 * 描边、圆盘都不必做 —— 这是实测里 77% 那一块（每像素迭代/覆盖计算）的直接来源。
630	 *
631	 * 判据必须**保守**：盒要按描边半宽、AA 余量外扩后再比，宁可多画也不能漏画。
632	 * 这是纯前置闸门，不改变任何像素。
633	 */
634	static bool box_may_write(const vmap_canvas_t * c, int32_t x1, int32_t y1,
635	    int32_t x2, int32_t y2)
636	{
637	    uint8_t i;
638	
639	    if (!c || x2 < 0 || y2 < 0 || x1 > c->w - 1 || y1 > c->h - 1) {
640	        return false;
641	    }
642	    if (c->clip_n == 0u) {
643	        return true;
644	    }
645	
646	    /* 裁剪矩形是半开区间 [clip_x1, clip_x2)，且加入时已夹到画布内。 */
647	    for (i = 0u; i < c->clip_n; i++) {
648	        if (x2 >= c->clip_x1[i] && x1 < c->clip_x2[i]
649	            && y2 >= c->clip_y1[i] && y1 < c->clip_y2[i]) {
650	            return true;
651	        }
652	    }
653	    return false;
654	}
