672	/** @brief 对 [x0,x1] 内的像素按覆盖度落笔（覆盖 <=0 的自动跳过）。 */
673	static void cover_partial_px(uint16_t * row, int32_t x0, int32_t x1,
674	    int32_t x0_fp, int32_t x1_fp, uint16_t color)
675	{
676	    int32_t x;
677	
678	    for (x = x0; x <= x1; x++) {
679	        const int32_t px0_fp = x << VMAP_FP_SHIFT;
680	        const int32_t px1_fp = px0_fp + VMAP_FP_ONE;
681	        const int32_t a_fp = x0_fp > px0_fp ? x0_fp : px0_fp;
682	        const int32_t b_fp = x1_fp < px1_fp ? x1_fp : px1_fp;
683	        const int32_t cov_fp = b_fp - a_fp;
684	
685	        if (cov_fp <= 0) {
686	            continue;
687	        }
688	        if (cov_fp >= VMAP_FP_ONE) {
689	            row[x] = color;
690	            STAT_STORE(2);
691	            continue;
692	        }
693	        blend_row_pixel(row, x, color,
694	            (uint8_t)(((uint32_t)cov_fp * 255U) >> VMAP_FP_SHIFT));
695	    }
696	}
