/* ★★ SIM 临时取证（WP-VERIFY1）：整数/定点填充的规模统计，**不含任何像素逻辑**。
 * 目的：① 确认整数版真的在跑真实面要素；② 看 xs[64] 交叉点上限、n>256 兜底
 * 是否被触发（触发就意味着整行配对错位 ⇒ 面被填反）。 */
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    unsigned long calls;
    unsigned long rows;
    unsigned long cross;
    unsigned long max_n;
    unsigned long max_cnt;
    unsigned long n_gt_cap;      /* n > 64：单行交叉点可能被截断 */
    unsigned long cnt_eq_64;     /* 单行恰好攒满 64 个交点（被截断） */
    unsigned long zero_span_row; /* 有边但配对后跨度为 0 的行（退化/自交） */
    unsigned long thin_calls;    /* 包围盒高度 <= 3 行的调用（细长条） */
    unsigned long tiny_x;        /* 交点 x 的最小/最大（看是否越界） */
    long min_x;
    long max_x;
} sim_probe_t;

static sim_probe_t s_probe_int;
static sim_probe_t s_probe_fp;

static void sim_probe_dump_one(const char *tag, const sim_probe_t *p)
{
    fprintf(stderr,
        "[probe] %s calls=%lu rows=%lu cross=%lu max_n=%lu max_cnt=%lu "
        "n_gt64=%lu cnt64=%lu zerospan=%lu thin=%lu x=[%ld,%ld]\n",
        tag, p->calls, p->rows, p->cross, p->max_n, p->max_cnt,
        p->n_gt_cap, p->cnt_eq_64, p->zero_span_row, p->thin_calls,
        p->min_x, p->max_x);
}

static void sim_probe_dump(void)
{
    sim_probe_dump_one("int", &s_probe_int);
    sim_probe_dump_one("fp ", &s_probe_fp);
}

static void sim_probe_init(void)
{
    static int done;
    if (!done) {
        done = 1;
        atexit(sim_probe_dump);
    }
}

static void sim_probe_enter(sim_probe_t *p, int32_t n, int32_t h)
{
    sim_probe_init();
    p->calls++;
    if ((unsigned long)n > p->max_n) {
        p->max_n = (unsigned long)n;
    }
    if (n > 64) {
        p->n_gt_cap++;
    }
    if (h >= 0 && h <= 3) {
        p->thin_calls++;
    }
}

static void sim_probe_row(sim_probe_t *p, int32_t cnt, int32_t x_lo, int32_t x_hi)
{
    p->rows++;
    p->cross += (unsigned long)cnt;
    if ((unsigned long)cnt > p->max_cnt) {
        p->max_cnt = (unsigned long)cnt;
    }
    if (cnt >= 64) {
        p->cnt_eq_64++;
    }
    if (cnt >= 2 && x_hi <= x_lo) {
        p->zero_span_row++;
    }
    if (cnt > 0) {
        if (x_lo < p->min_x) { p->min_x = x_lo; }
        if (x_hi > p->max_x) { p->max_x = x_hi; }
    }
}
