"""WP-VERIFY1 对照实验：把**整数版 fill_polygon 换成定点版 fill_polygon_fp**。

用法：python3 fp_swap_patch.py /path/to/lvgl_sim/build_fp/ui_port/vendor_patched/vmap_render.c
只作用于构建期生成的模拟器副本（产物），vendor 源码一行不动。

做法：整数顶点 (x,y) 按 `<< VMAP_FP_SHIFT` 原样映射到定点域，再走
`fill_polygon_fp()` —— 同一批几何、同一套 DDA，唯一差别是定点版按**行中心**
(y*256+128) 采样、整数版按**行首** (y) 采样。像素差异因此只应落在面要素边缘
的 1px 带内；出现成块差异就是整数版的填充缺陷。
"""
import sys

PATH = sys.argv[1]
src = open(PATH, encoding="utf-8").read()

START = "static void fill_polygon(vmap_canvas_t * c, const vmap_point_t * pts, int32_t n,\n    uint16_t color)\n{"
assert src.count(START) == 1, src.count(START)
i = src.index(START)
# 从函数起点开始找配对的右花括号
depth = 0
j = src.index("{", i)
k = j
while True:
    ch = src[k]
    if ch == "{":
        depth += 1
    elif ch == "}":
        depth -= 1
        if depth == 0:
            break
    k += 1
old = src[i:k + 1]

NEW = '''/* ★★ SIM 临时对照（WP-VERIFY1）：整数版 fill_polygon 换成定点版。
 * 顶点按 <<VMAP_FP_SHIFT 原样映射，几何完全相同；用于 A/B 逐像素对比。 */
#define SIM_FP_SWAP_CAP 1024

static void fill_polygon(vmap_canvas_t * c, const vmap_point_t * pts, int32_t n,
    uint16_t color)
{
    static vmap_fp_point_t s_sim_fp[2][SIM_FP_SWAP_CAP];
    static int s_sim_fp_ix;
    vmap_fp_point_t * q;
    int32_t i;

    if (n < 3) {
        return;
    }
    if (n > SIM_FP_SWAP_CAP) {
        n = SIM_FP_SWAP_CAP;        /* 真实负载最大 437 点，这里只是兜底 */
    }
    q = s_sim_fp[s_sim_fp_ix & 1];
    s_sim_fp_ix++;
    for (i = 0; i < n; i++) {
        q[i].x = (int32_t)((int64_t)pts[i].x << VMAP_FP_SHIFT);
        q[i].y = (int32_t)((int64_t)pts[i].y << VMAP_FP_SHIFT);
    }
    fill_polygon_fp(c, q, n, color);
}'''

open(PATH, "w", encoding="utf-8").write(src[:i] + NEW + src[k + 1:])
print("fp swap applied to", PATH, "(%d bytes replaced)" % len(old))
