CODE = r'''

/* ★★ SIM 临时取证（WP-VERIFY1）：只经整数版 fill_polygon 的合成用例。 */
#include <stdio.h>
#include <stdlib.h>
#include "vmap_alloc.h"

#define SIM_U_W 96
#define SIM_U_H 72

static void sim_u_dump(const char *dir, const char *name, const vmap_canvas_t *c)
{
    char path[512];
    FILE *fp;

    snprintf(path, sizeof(path), "%s/%s.ppm", dir, name);
    fp = fopen(path, "wb");
    if (!fp) {
        return;
    }
    fprintf(fp, "P6\n%d %d\n255\n", (int)c->w, (int)c->h);
    for (int32_t y = 0; y < c->h; y++) {
        const uint16_t *row = (const uint16_t *)((const uint8_t *)c->buf
            + (size_t)y * c->stride);

        for (int32_t x = 0; x < c->w; x++) {
            const uint16_t p = row[x];
            const unsigned char rgb[3] = {
                (unsigned char)(((p >> 11) & 0x1f) << 3),
                (unsigned char)(((p >> 5) & 0x3f) << 2),
                (unsigned char)((p & 0x1f) << 3)
            };
            fwrite(rgb, 1, 3, fp);
        }
    }
    fclose(fp);
}

static vmap_canvas_t *sim_u_begin(uint16_t *fb, uint16_t fill)
{
    static vmap_canvas_t c;
    memset(&c, 0, sizeof(c));
    for (int32_t i = 0; i < SIM_U_W * SIM_U_H; i++) {
        fb[i] = fill;
    }
    c.buf = fb;
    c.w = SIM_U_W;
    c.h = SIM_U_H;
    c.stride = SIM_U_W * 2;
    vmap_render_clip_reset(&c);
    vmap_render_clip_add(&c, 0, 0, SIM_U_W, SIM_U_H);
    return &c;
}

static void sim_u_run(void)
{
    const char *dir = getenv("SIM_VMAP_UNIT");
    uint16_t *fb;

    if (dir == NULL || dir[0] == '\0') {
        return;
    }
    fb = (uint16_t *)vmap_malloc((size_t)SIM_U_W * SIM_U_H * sizeof(uint16_t));
    if (fb == NULL) {
        return;
    }
    vmap_prim_init();

    /* ring：外框 (10,10)-(80,60)，经零宽缝连到内孔 (30,25)-(60,45) */
    {
        vmap_point_t p[] = {
            { 10, 30 }, { 10, 10 }, { 80, 10 }, { 80, 60 }, { 10, 60 }, { 10, 30 },
            { 30, 30 }, { 30, 25 }, { 60, 25 }, { 60, 45 }, { 30, 45 }, { 30, 30 }
        };
        vmap_canvas_t *c = sim_u_begin(fb, 0xFFFFu);
        fill_polygon(c, p, (int32_t)(sizeof(p) / sizeof(p[0])), 0x001Fu);
        sim_u_dump(dir, "ring", c);
    }

    /* thin：五种细条 */
    {
        vmap_canvas_t *c = sim_u_begin(fb, 0xFFFFu);
        vmap_point_t h[] = { { 5, 5 }, { 90, 5 }, { 90, 6 }, { 5, 6 } };
        vmap_point_t v[] = { { 10, 10 }, { 11, 10 }, { 11, 68 }, { 10, 68 } };
        vmap_point_t d[] = { { 20, 60 }, { 60, 20 }, { 61, 21 }, { 21, 61 } };
        vmap_point_t s[] = { { 5, 40 }, { 90, 48 }, { 90, 49 }, { 5, 41 } };
        vmap_point_t t[] = { { 70, 62 }, { 72, 62 }, { 72, 63 }, { 70, 63 } };
        fill_polygon(c, h, 4, 0x001Fu);
        fill_polygon(c, v, 4, 0x001Fu);
        fill_polygon(c, d, 4, 0x001Fu);
        fill_polygon(c, s, 4, 0x001Fu);
        fill_polygon(c, t, 4, 0x001Fu);
        sim_u_dump(dir, "thin", c);
    }

    /* adj：两块共用 x=48 这条边 */
    {
        vmap_canvas_t *c = sim_u_begin(fb, 0xFFFFu);
        vmap_point_t a[] = { { 10, 10 }, { 48, 10 }, { 48, 60 }, { 10, 60 } };
        vmap_point_t b[] = { { 48, 10 }, { 86, 10 }, { 86, 60 }, { 48, 60 } };
        fill_polygon(c, a, 4, 0x001Fu);
        fill_polygon(c, b, 4, 0xF800u);
        sim_u_dump(dir, "adj", c);
    }

    /* degen：重复首点 / 水平退化边 / 单点尖峰 */
    {
        vmap_canvas_t *c = sim_u_begin(fb, 0xFFFFu);
        vmap_point_t a[] = { { 10, 10 }, { 10, 10 }, { 80, 10 }, { 80, 60 },
                             { 10, 60 }, { 10, 10 } };
        vmap_point_t b[] = { { 20, 50 }, { 40, 30 }, { 60, 50 }, { 40, 70 } };
        fill_polygon(c, a, 6, 0x001Fu);
        fill_polygon(c, b, 4, 0xF800u);
        sim_u_dump(dir, "degen", c);
    }

    /* quad：随机细长四边形（旧"整数丝带"的负载形状） */
    {
        vmap_canvas_t *c = sim_u_begin(fb, 0xFFFFu);
        uint32_t rng = 0x12345678u;
        for (int k = 0; k < 24; k++) {
            vmap_point_t q[4];
            int32_t x0, y0, x1, y1, hw;
            rng = rng * 1664525u + 1013904223u; x0 = 2 + (int32_t)((rng >> 8) % 90);
            rng = rng * 1664525u + 1013904223u; y0 = 2 + (int32_t)((rng >> 8) % 66);
            rng = rng * 1664525u + 1013904223u; x1 = 2 + (int32_t)((rng >> 8) % 90);
            rng = rng * 1664525u + 1013904223u; y1 = 2 + (int32_t)((rng >> 8) % 66);
            rng = rng * 1664525u + 1013904223u; hw = 1 + (int32_t)((rng >> 8) % 3);
            q[0].x = x0; q[0].y = y0 - hw;
            q[1].x = x1; q[1].y = y1 - hw;
            q[2].x = x1; q[2].y = y1 + hw;
            q[3].x = x0; q[3].y = y0 + hw;
            fill_polygon(c, q, 4, 0x001Fu);
        }
        sim_u_dump(dir, "quad", c);
    }

    vmap_free(fb);
}

__attribute__((constructor)) static void sim_u_ctor(void)
{
    sim_u_run();
}
'''

